<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';if(isPost()){requireCsrf();$name=requestString('name');$email=filter_var(requestString('email'),FILTER_VALIDATE_EMAIL);$subject=requestString('subject');$message=requestString('message');if(!$name||!$email||!$subject||!$message)flash('error','Please complete all fields.');else{$pdo->prepare('INSERT INTO contact_messages(name,email,phone,subject,message,ip_address) VALUES(?,?,?,?,?,?)')->execute([$name,$email,requestString('phone'),$subject,$message,clientIp()]);flash('success','Thank you. Your message has been sent.');redirect('/contact.php');}}$pageTitle='Contact Luméa Beauty';require __DIR__.'/includes/header.php';?><section class="page-title"><span class="eyebrow">WE ARE HERE FOR YOU</span><h1>Contact Us</h1><p>Questions about products, orders or your beauty routine? We'd love to help.</p></section><section class="container checkout-layout" style="padding-bottom:70px"><form class="form-card" method="post"><?=csrfField()?><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Subject</label><input name="subject" required></div><div class="field full"><label>Message</label><textarea name="message" rows="7" required></textarea></div></div><button class="btn primary">Send Message</button></form><aside class="panel"><h3>Need Help?</h3><p><i class="bi bi-envelope"></i> <?=e((string)setting($pdo,'contact_email','hello@lumeabeauty.local'))?></p><p><i class="bi bi-telephone"></i> <?=e((string)setting($pdo,'contact_phone','+92 300 0000000'))?></p><p><i class="bi bi-clock"></i> <?=e((string)setting($pdo,'business_hours','Mon-Sat, 10 AM-8 PM'))?></p><?php $wa=preg_replace('/\D+/','',(string)setting($pdo,'whatsapp','+92 300 0000000'));?><a class="btn primary" href="https://wa.me/<?=e($wa)?>" target="_blank" rel="noopener">WhatsApp Us</a></aside></section><?php require __DIR__.'/includes/footer.php';?>
